interface User { id: number; name: string; suspended: boolean }
type LoadError = "not-found" | "suspended";

const users: User[] = [
  { id: 1, name: "Ada", suspended: false },
  { id: 2, name: "Eve", suspended: true },
];

function loadUser(id: number): Result<User, LoadError> {
  const user = users.find((u) => u.id === id);
  if (user === undefined) return { ok: false, error: "not-found" };
  if (user.suspended) return { ok: false, error: "suspended" };
  return { ok: true, value: user };
}

for (const id of [1, 2, 3]) {
  const result = loadUser(id);
  console.log(result.ok ? result.value.name : result.error);
}

interface Entity {
  readonly id: number;
}

class MemoryRepository<T extends Entity> {
  private readonly items = new Map<number, T>();

  async save(item: T): Promise<T> {
    this.items.set(item.id, item);
    return item;
  }

  async findById(id: number): Promise<T | undefined> {
    return this.items.get(id);
  }

  async findWhere(match: (item: T) => boolean): Promise<T[]> {
    return [...this.items.values()].filter(match);
  }
}

interface Task extends Entity { title: string; done: boolean }

