function zip<A, B>(left: readonly A[], right: readonly B[]): [A, B][] {
  const pairs: [A, B][] = [];
  const length = Math.min(left.length, right.length);
  for (let i = 0; i < length; i++) {
    pairs.push([left[i], right[i]]);
  }
  return pairs;
}

